 'look-cozy':[[12,50.5,98.6,91.1],[13.4,48.8,91.1,89],[14,47.8,91.6,89.2],[15.6,47.6,98.1,89]],
 'look-star':[[65,23.4,90.9,51],[59.1,15.6,81.6,38.3],[62.9,36.8,82.5,56],[54.5,45.9,71.5,62.7]],
